  ('343377d3-cba8-40bd-93f0-366e95d46313', 'd8e9f0a1-2b3c-4d50-9e00-0f1a2b3c4d20', '2d824e26-86e3-4369-b1d1-a9fa23369b92', 'concept'::public.curated_course_node_type, 'Latency, failed messages, duplicates, reconciliation, and error handling', null, 0),
