  ('0d4f52b5-d369-4c51-bed6-4705c8236ba6', 'd8e9f0a1-2b3c-4d50-9e00-0f1a2b3c4d20', '280d310b-c5a6-4323-a6dc-41858ee47d9a', 'subtopic'::public.curated_course_node_type, 'Platform Capabilities', 'The goal is to see modern ERP as a platform, not just a transaction system.', 1),
