  ('2452c097-c8f5-4127-a742-2f548454d44e', 'd8e9f0a1-2b3c-4d50-9e00-0f1a2b3c4d20', '279a5f0a-ae5a-4d32-9092-3983f9867e21', 'concept'::public.curated_course_node_type, 'Availability, backup, disaster recovery, observability, and incident management', null, 0),
