  ('bd20dcd1-90d0-47ab-9f30-a7e6db28e182', 'd8e9f0a1-2b3c-4d50-9e00-0f1a2b3c4d20', '279a5f0a-ae5a-4d32-9092-3983f9867e21', 'concept'::public.curated_course_node_type, 'Cost management, licensing, and service-level agreements', null, 2),
